    function __ESBMC_assume(bool) internal pure {}

    function run(uint64 _number, uint256 _basefee) public {
        bool reverted;
        c.setL1BlockValues(_number, 0, _basefee, bytes32(0), 0, bytes32(0), 0, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted);
    }

    receive() external payable {}
